argv:
$ErrorActionPreference='Stop'
$dst='E:\boss-R67-QA-PORTABLE-VERIFY-20261014-GPT6'
$sha='f737a35ad9ea8463cdc59d6a92a0a0f7a2a80f93'
if(Test-Path -LiteralPath $dst){throw 'REFUSE_EXISTING_PATH'}
& git.exe clone --quiet --depth 1 --single-branch --no-tags --branch 'agent/qa-r67-portable-canary-regressions-20261014' 'https://github.com/foto6/boss.git' $dst
if($LASTEXITCODE -ne 0){throw 'QA_CLONE_FAILED'}
$head=([string](& git.exe -C $dst rev-parse HEAD)).Trim()
if($head -ne $sha){throw ('QA_BRANCH_MOVED '+$head)}
$nodeLog=Join-Path $dst 'R67_NODE_TEST.txt'
$pyLog=Join-Path $dst 'R67_PYTHON_TEST.txt'
Push-Location $dst
try{
 & node.exe --test tests/r65_autonomy_canary.test.cjs 2>&1|Out-File -LiteralPath $nodeLog -Encoding UTF8
 $nodeRc=$LASTEXITCODE
 $ErrorActionPreference='Continue'
 & python.exe -m unittest discover -s tests -v 2>&1|Out-File -LiteralPath $pyLog -Encoding UTF8
 $pyRc=$LASTEXITCODE
}finally{$ErrorActionPreference='Stop';Pop-Location}
Write-Output ('EXACT_SHA='+$head)
Write-Output ('NODE_RC='+$nodeRc)
Select-String -LiteralPath $nodeLog -Pattern '^ℹ (?:tests|pass|fail)|^✖'|Select-Object -Last 8|ForEach-Object{Write-Output $_.Line}
Write-Output ('PYTHON_RC='+$pyRc)
Get-Content -LiteralPath $pyLog -Tail 6
Write-Output ('PRODUCTION_BRIDGE_SHA='+(& git.exe -C 'E:\WebAIBridge' rev-parse HEAD))
Write-Output ('LOCAL_LOGS='+$nodeLog+' '+$pyLog)
if($nodeRc -ne 0 -or $pyRc -ne 0){throw 'R67_TESTS_NOT_GREEN'}
